using System;using System.Diagnostics;using System.IO;using System.Windows.Forms;
namespace LootLazy {static class Program {[STAThread]static void Main(){string baseDir=AppDomain.CurrentDomain.BaseDirectory;string[] candidates=new string[]{Path.Combine(baseDir,"dist","LootLazy-Tauri","LootLazy.exe"),Path.Combine(baseDir,"project","dist","LootLazy-Tauri","LootLazy.exe")};string target=null;foreach(string c in candidates){string p=c+".pending";if(File.Exists(p)){try{File.Copy(p,c,true);File.Delete(p);}catch(IOException){}catch(UnauthorizedAccessException){}}if(File.Exists(c)){target=c;break;}}if(target==null){MessageBox.Show("Build not found. Run npm run build from the project folder.","LootLazy");return;}try{Process.Start(new ProcessStartInfo{FileName=target,WorkingDirectory=Path.GetDirectoryName(target),UseShellExecute=false,CreateNoWindow=true});}catch(Exception e){MessageBox.Show(e.Message,"LootLazy");}}}}
